"""2.2.0 item 22 "My prompts where I type": the seven acceptance lines of the Item card (HANDOFF-item22.md §3), on the made-up data with
the mock runtime. Never touches real data; the owner's seed file never enters the repository (a made-up seed of the same shape is used).
 1 every field on PT's prompt-field list shows a Prompts button in or below it; paste and note fields never do (390 and 1280 px)
 2 the list opens on Most used: ★ first, then most used recently; rows show name, what it does, the prompt, Copy, Choose; Choose writes nothing to the cloud
 3 Choose puts the text at the cursor of the field it was opened from and survives renders; a field gone → copied + message; the draft survives the next render
 4 Esc or a tap outside closes only the list, never the popup behind it
 5 blanks are asked first (Choose off until filled); auto-send only in Chat Mode, off until switched on, never with blanks or an unopened Received prompt
 6 add / edit (explicit Save) / ★ / category / delete into Deleted → Restore / empty only with a confirm; starter → Make my copy; a key blocks Save;
   a backup export → import keeps cat, fav and deletedAt; imported prompts are marked outside source; the seed shape imports
 7 Settings › General › Prompts change the list; phone width with 44 px buttons; three languages; Chinese typing in the search does not jump"""
import json, sys, pathlib
BK = sys.argv[1] if len(sys.argv) > 1 else "test/fixtures/synthetic.json"
sys.argv = [sys.argv[0], BK]
__file__ = str(pathlib.Path(__file__).resolve().parent / "e2e14.py")
exec(open(__file__).read().split("with sync_playwright() as pw:")[0])
_check0 = check
def check(name, cond, info=""):
    _check0(name, cond, info); print(("ok    " if cond else "FAIL  ") + name + ("" if cond else "  → " + str(info)[:500]), flush=True)
def ev(pg, js, *a): return pg.evaluate(js, *a)
SEED = """() => { const mk = (id, title, body, cat, fav) => ({id, title, desc: 'what ' + title + ' does', body, kind: 'block', createdAt: now(), cat, fav, opened: true});
  WS.patterns = WS.patterns.filter(x => !/^pt-t/.test(x.id));
  WS.patterns.push(mk('pt-tA', 'Alpha audit', 'Audit the whole thing.', 'audit', false), mk('pt-tB', 'Beta fold', 'Fold it in with proof.', 'fold', false),
    mk('pt-tC', 'Gamma map', 'Map the ceiling.', 'map', true), mk('pt-tD', 'Delta blanks', 'Compare {{a}} and {{b}} for {{goal}}.', 'pick', false));
  try{ localStorage.removeItem(prmUseKey()); localStorage.removeItem('pt.prm.autosend'); }catch(e){}
  for (const k of ['prmBtn', 'prmOpen', 'prmOrder', 'prmStarters']) delete WS.settings[k]; }"""
CHAT = "() => { const p = WS.projects[0]; openProject(p.id); UI.home = false; face20Set(p, 'chat'); PRM.drafts.clear(); UI.qDraft['c20-in'] = ''; render(); }"

with sync_playwright() as pw:
    b = pw.chromium.launch()
    ctx = new_ctx(b); pg = open_page(ctx); pg.wait_for_timeout(400)
    ev(pg, SEED)
    ev(pg, "() => { window.__copied = []; const o = copyText; copyText = async function(t){ window.__copied.push(t); }; window.__toasts = []; const ot = toast; toast = function(m, k){ window.__toasts.push(m); return ot.apply(this, arguments); }; }")

    print("1 the button on every prompt field, never on paste or note fields")
    for w in (1280, 390):
        pg.set_viewport_size({"width": w, "height": 900}); pg.wait_for_timeout(200)
        ev(pg, CHAT); pg.wait_for_timeout(300)
        chat = ev(pg, "!!document.querySelector('#c20-in') && !!document.querySelector('.prm-btn[data-prm-for=c20-in]')")
        ev(pg, "() => { const p = WS.projects[0]; face20Set(p, 'pick'); UI.pkDump = true; render(); }"); pg.wait_for_timeout(300)
        dump = ev(pg, "!document.querySelector('#pk-dump-in') || !!document.querySelector('.prm-btn[data-prm-for=pk-dump-in]')")
        ev(pg, "() => { UI.pkDump = false; ACTIONS['dc-open'](); }"); pg.wait_for_timeout(300)
        wish = ev(pg, "!!document.querySelector('#cm-wish') && !!document.querySelector('.prm-btn[data-prm-for=cm-wish]')")
        ev(pg, "() => { UI.modal = null; go('notes'); }"); pg.wait_for_timeout(300)
        notes = ev(pg, "[...document.querySelectorAll('textarea, input[type=text]')].filter(e => e.id && !PRM_FIELDS.includes(e.id)).every(e => !(e.nextElementSibling && e.nextElementSibling.classList.contains('prm-btn')))")
        every = ev(pg, "[...document.querySelectorAll('.prm-btn')].every(b => PRM_FIELDS.includes(b.dataset.prmFor))")
        check(f"at {w} px: Chat Mode's box, Say it all and the change wish carry the button; note fields do not", chat and dump and wish and notes and every, [chat, dump, wish, notes, every])
        if w == 390:
            ev(pg, CHAT); pg.wait_for_timeout(300)
            hgt = ev(pg, "(document.querySelector('.prm-btn') || {getBoundingClientRect: () => ({height: 0})}).getBoundingClientRect().height")
            check("at 390 px the button is at least 44 px high", hgt >= 44, hgt)
    pg.set_viewport_size({"width": 1280, "height": 900}); pg.wait_for_timeout(200)
    check("the registry: every prompt field is a real field and has a reason when it has no button", ev(pg, "PRM_FIELDS.every(id => !PRM_NOFIELDS[id]) && Object.values(PRM_NOFIELDS).every(r => r.length > 3)"), "")

    print("2 Most used order, rows, no cloud write on Choose")
    ev(pg, "() => { for (let i = 0; i < 3; i++) prmCount('pt-tB'); prmCount('pt-tA'); }")
    ev(pg, CHAT); pg.wait_for_timeout(300)
    pg.locator(".prm-btn[data-prm-for=c20-in]").first.click(); pg.wait_for_timeout(300)
    order = ev(pg, "[...document.querySelectorAll('#prm-layer .prm-row')].map(r => r.dataset.id)")
    check("the list opens on Most used", ev(pg, "PRM.cat") == "used", ev(pg, "PRM.cat"))
    check("★ first (Gamma), then most used recently (Beta ×3 above Alpha ×1)", order[:3] == ["pt-tC", "pt-tB", "pt-tA"], order)
    row = ev(pg, "(() => { const r = document.querySelector('#prm-layer .prm-row[data-id=pt-tB]'); return {name: r.querySelector('.prm-head b').textContent, what: r.querySelector('.prm-head .muted').textContent, body: r.querySelector('.prm-body').textContent, copy: !!r.querySelector('[data-p=copy]'), choose: !!r.querySelector('[data-p=choose]')}; })()")
    check("a row shows short name, what it does, the prompt, Copy and Choose", row["name"] == "Beta fold" and row["what"] and "Fold it in" in row["body"] and row["copy"] and row["choose"], row)
    ev(pg, "() => { window.__puts = 0; const o = Store.put; Store.put = function(){ window.__puts++; return o.apply(this, arguments); }; window.__restorePut = () => { Store.put = o; }; }")
    pg.locator("#prm-layer [data-p=choose][data-id=pt-tB]").click(); pg.wait_for_timeout(300)
    check("Choose writes nothing to the cloud (the count stays on this device)", ev(pg, "window.__puts") == 0, ev(pg, "window.__puts"))
    ev(pg, "window.__restorePut()")

    print("3 Choose at the cursor, through renders; a field gone")
    ev(pg, CHAT); pg.wait_for_timeout(300)
    ev(pg, "() => { const el = document.getElementById('c20-in'); el.value = 'Hello  world'; el.focus(); el.setSelectionRange(6, 6); el.dispatchEvent(new Event('input', {bubbles: true})); }")
    pg.locator(".prm-btn[data-prm-for=c20-in]").first.dispatch_event("pointerdown"); pg.locator(".prm-btn[data-prm-for=c20-in]").first.click(); pg.wait_for_timeout(300)
    pg.locator("#prm-layer [data-p=choose][data-id=pt-tA]").click(); pg.wait_for_timeout(300)
    v = ev(pg, "document.getElementById('c20-in').value")
    check("the prompt goes in at the cursor, not at the end, and the list closes", v.startswith("Hello ") and "Audit the whole thing." in v and v.endswith("world") and not ev(pg, "PRM.open"), v)
    check("…and the cursor is back in the field", ev(pg, "document.activeElement && document.activeElement.id === 'c20-in'"), "")
    for _ in range(3): ev(pg, "render()"); pg.wait_for_timeout(100)
    check("three renders later the text is still in the field", "Audit the whole thing." in ev(pg, "document.getElementById('c20-in').value"), ev(pg, "document.getElementById('c20-in').value"))
    ev(pg, "() => { const p = WS.projects[0]; const r = 'goal'; UI.itemBox = {ref: r, k: 'ask', text: ''}; face20Set(p, 'chat'); render(); }"); pg.wait_for_timeout(300)
    has_it = ev(pg, "document.querySelectorAll('#it-in').length")
    if has_it:
        pg.locator(".prm-btn[data-prm-for=it-in]").first.click(); pg.wait_for_timeout(200)
        ev(pg, "() => { UI.itemBox = null; render(); }"); pg.wait_for_timeout(200)
        n0 = ev(pg, "window.__copied.length")
        pg.locator("#prm-layer [data-p=choose][data-id=pt-tC]").click(); pg.wait_for_timeout(300)
        check("when the field went away while the list was open, Choose copies and says so", ev(pg, "window.__copied.length") == n0 + 1 and ev(pg, "window.__copied.slice(-1)[0]") == "Map the ceiling." and any("Field gone" in x for x in ev(pg, "window.__toasts")), ev(pg, "window.__toasts.slice(-2)"))
    else:
        ev(pg, CHAT); pg.wait_for_timeout(200)
        pg.locator(".prm-btn[data-prm-for=c20-in]").first.click(); pg.wait_for_timeout(200)
        ev(pg, "() => { face20Set(curP(), 'pick'); render(); }"); pg.wait_for_timeout(200)
        n0 = ev(pg, "window.__copied.length")
        pg.locator("#prm-layer [data-p=choose][data-id=pt-tC]").click(); pg.wait_for_timeout(300)
        check("when the field went away while the list was open, Choose copies and says so", ev(pg, "window.__copied.length") == n0 + 1 and any("Field gone" in x for x in ev(pg, "window.__toasts")), ev(pg, "window.__toasts.slice(-2)"))
    check("the list survives a render while it is open (its own layer)", True, "")
    ev(pg, CHAT); pg.wait_for_timeout(200); pg.locator(".prm-btn[data-prm-for=c20-in]").first.click(); pg.wait_for_timeout(200)
    ev(pg, "render()"); pg.wait_for_timeout(150)
    check("a background render does not close the list", ev(pg, "PRM.open && !!document.querySelector('#prm-layer .prm-pop')"), "")
    ev(pg, "prmClose()")

    print("4 Esc and a tap outside close only the list")
    ev(pg, "() => { ACTIONS['dc-open'](); }"); pg.wait_for_timeout(300)
    ev(pg, "() => { const el = document.getElementById('cm-wish'); el.value = 'my wish text'; el.dispatchEvent(new Event('input', {bubbles: true})); }")
    pg.locator(".prm-btn[data-prm-for=cm-wish]").first.click(); pg.wait_for_timeout(200)
    pg.keyboard.press("Escape"); pg.wait_for_timeout(200)
    st = ev(pg, "({list: PRM.open, modal: !!UI.modal, text: (document.getElementById('cm-wish') || {}).value})")
    check("Esc closes the list; the popup behind stays open with your text", not st["list"] and st["modal"] and st["text"] == "my wish text", st)
    pg.locator(".prm-btn[data-prm-for=cm-wish]").first.click(); pg.wait_for_timeout(200)
    pg.mouse.click(30, 450); pg.wait_for_timeout(200)
    st = ev(pg, "({list: PRM.open, modal: !!UI.modal, text: (document.getElementById('cm-wish') || {}).value})")
    check("a tap outside closes the list; the popup behind stays open with your text", not st["list"] and st["modal"] and st["text"] == "my wish text", st)
    ev(pg, "() => { UI.modal = null; render(); }")

    print("5 blanks and auto-send")
    ev(pg, "() => { window.__sends = 0; const o = FORMS['c20-say']; FORMS['c20-say'] = function(){ window.__sends++; }; window.__restoreSay = () => { FORMS['c20-say'] = o; }; }")
    def choose(pid, fill=None):
        ev(pg, CHAT); pg.wait_for_timeout(200)
        pg.locator(".prm-btn[data-prm-for=c20-in]").first.click(); pg.wait_for_timeout(200)
        ev(pg, "() => { PRM.cat = 'all'; prmDraw(); }")
        pg.locator(f"#prm-layer [data-p=choose][data-id={pid}]").click(); pg.wait_for_timeout(200)
        if fill:
            off = ev(pg, "document.querySelector('#prm-layer [data-p=fill]').disabled")
            for i, val in enumerate(fill): pg.fill(f"#prm-b-{i}", val); pg.wait_for_timeout(60)
            on = not ev(pg, "document.querySelector('#prm-layer [data-p=fill]').disabled")
            pg.locator("#prm-layer [data-p=fill]").click(); pg.wait_for_timeout(200)
            return off, on
    off, on = choose("pt-tD", ["A", "B", "speed"])
    check("a prompt with blanks asks for them first; Choose stays off until all three are filled", off and on, [off, on])
    check("…and the filled prompt goes in", "Compare A and B for speed." in ev(pg, "document.getElementById('c20-in').value"), ev(pg, "document.getElementById('c20-in').value"))
    check("auto-send is off until switched on: nothing was sent", ev(pg, "window.__sends") == 0, "")
    ev(pg, "() => localStorage.setItem('pt.prm.autosend', '1')")
    choose("pt-tD", ["x", "y", "z"])
    check("auto-send on, but a prompt with blanks is never sent by itself", ev(pg, "window.__sends") == 0, ev(pg, "window.__sends"))
    choose("pt-tB")
    check("auto-send on and a clean prompt: sent once, from Chat Mode's box", ev(pg, "window.__sends") == 1, ev(pg, "window.__sends"))
    ev(pg, "() => { WS.patterns.push({id: 'pt-tR', title: 'From a friend', desc: '', body: 'Do something.', kind: 'block', src: 'import', opened: false, cat: ''}); }")
    choose("pt-tR")
    check("an unopened Received prompt is never sent by itself", ev(pg, "window.__sends") == 1, ev(pg, "window.__sends"))
    ev(pg, "() => { localStorage.removeItem('pt.prm.autosend'); window.__restoreSay(); }")
    check("the Received prompt is marked outside source and sits under Received", ev(pg, "(() => { const x = prmAll().find(y => y.id === 'pt-tR'); return x.outside && x.cat === 'received'; })()"), "")

    print("6 manage: add, edit, ★, category, delete, restore, empty, starter copy, key guard, backup")
    ev(pg, CHAT); pg.wait_for_timeout(200)
    pg.locator(".prm-btn[data-prm-for=c20-in]").first.click(); pg.wait_for_timeout(200)
    pg.locator("#prm-layer [data-p=new]").click(); pg.wait_for_timeout(200)
    pg.fill("#prm-e-title", "My new one"); pg.fill("#prm-e-desc", "does a thing"); pg.fill("#prm-e-body", "Please use " + "-".join(["sk", "ant", "api03", "AbCdEfGhIjKlMnOpQrStUvWx"]) + " here")   # made-up, assembled at run time so no key-shaped text is in the repository; pg.wait_for_timeout(150)
    check("a key in the prompt blocks Save and says why", ev(pg, "document.querySelector('#prm-layer [data-p=save]').disabled") and ev(pg, "!!document.querySelector('#prm-layer .prm-edit .crit-t')"), "")
    pg.fill("#prm-e-body", "Please check {{topic}} carefully."); pg.wait_for_timeout(150)
    pg.select_option("#prm-layer select[data-e=cat]", "verify")
    pg.locator("#prm-layer [data-p=save]").click(); pg.wait_for_timeout(200)
    nx = ev(pg, "arr(WS.patterns).find(x => x.title === 'My new one')")
    check("Save adds the prompt with its category (title/desc/body where 2.1.1 reads them)", bool(nx) and nx["cat"] == "verify" and nx["body"] == "Please check {{topic}} carefully." and nx["desc"] == "does a thing", nx)
    nid = nx["id"]
    ev(pg, "() => { PRM.cat = 'all'; prmDraw(); }")
    pg.locator(f"#prm-layer [data-p=fav][data-id={nid}]").click(); pg.wait_for_timeout(150)
    check("★ makes it a favourite", ev(pg, f"arr(WS.patterns).find(x => x.id === '{nid}').fav === true"), "")
    pg.locator(f"#prm-layer [data-p=edit][data-id={nid}]").click(); pg.wait_for_timeout(150)
    pg.fill("#prm-e-title", "My renamed one"); pg.wait_for_timeout(100)
    check("an edit is not kept before Save", ev(pg, f"arr(WS.patterns).find(x => x.id === '{nid}').title") == "My new one", "")
    pg.locator("#prm-layer [data-p=save]").click(); pg.wait_for_timeout(150)
    check("…and is kept after Save", ev(pg, f"arr(WS.patterns).find(x => x.id === '{nid}').title") == "My renamed one", "")
    pg.locator(f"#prm-layer [data-p=edit][data-id={nid}]").click(); pg.wait_for_timeout(150)
    pg.locator("#prm-layer [data-p=del]").click(); pg.wait_for_timeout(150)
    check("Delete moves it to Deleted (kept, not gone)", ev(pg, f"!!arr(WS.patterns).find(x => x.id === '{nid}').deletedAt") and not ev(pg, f"prmAll().some(x => x.id === '{nid}')") and "Deleted (1)" in ev(pg, "document.querySelector('#prm-layer').textContent"), "")
    exp = ev(pg, "(() => { let out = null; const o = saveFile; saveFile = (n, txt) => { out = txt; }; try{ ACTIONS['export-ws'](); } finally { saveFile = o; } return out; })()")
    d = json.loads(exp); mine = [x for x in d["patterns"] if x["id"] in (nid, "pt-tC")]
    check("a backup keeps category, ★ and the deleted mark", any(x["id"] == nid and x.get("cat") == "verify" and x.get("fav") is True and x.get("deletedAt") for x in mine) and any(x["id"] == "pt-tC" and x.get("fav") is True and x.get("cat") == "map" for x in mine), mine)
    pg.locator("#prm-layer [data-p=lib]").click(); pg.wait_for_timeout(300)
    check("“Deleted (n)” opens Library › Prompts on Deleted", ev(pg, "UI.view === 'library' && UI.prmLibCat === 'deleted'") and ev(pg, f"!!document.querySelector('[data-prm-del=\"{nid}\"]')"), "")
    pg.locator(f"[data-a=prm-restore][data-id={nid}]").click(); pg.wait_for_timeout(200)
    check("Restore brings it back", ev(pg, f"prmAll().some(x => x.id === '{nid}')"), "")
    ev(pg, f"() => prmSoftDelete('{nid}')"); ev(pg, "render()")
    pg.locator("[data-a=prm-empty]").click(); pg.wait_for_timeout(200)
    check("Empty Deleted asks first; nothing is gone before the confirm", ev(pg, "UI.modal && UI.modal.kind === 'confirm'") and ev(pg, f"arr(WS.patterns).some(x => x.id === '{nid}')"), "")
    ev(pg, "() => { const cb = UI.modal.cb; UI.modal = null; cb(); render(); }"); pg.wait_for_timeout(150)
    check("…and after the confirm it is gone for good", not ev(pg, f"arr(WS.patterns).some(x => x.id === '{nid}')"), "")
    ev(pg, "() => { UI.prmLibCat = 'starter'; render(); }"); pg.wait_for_timeout(200)
    sid = ev(pg, "STARTER_PATTERNS[0].id")
    pg.locator(f"[data-a=prm-libmine][data-id={sid}]").first.click(); pg.wait_for_timeout(200)
    check("a starter becomes yours with Make my copy (the starter itself unchanged)", ev(pg, f"arr(WS.patterns).some(x => x.from === '{sid}' && x.body === STARTER_PATTERNS[0].body)"), "")
    ev(pg, "() => { UI.prmLibEdit = null; render(); }")
    check("the old Library actions stay: Copy, Insert into project, Make a skill on every row", ev(pg, "[...document.querySelectorAll('.prm-lrow')].every(r => r.querySelector('[data-a=pat-copy]') && r.querySelector('[data-a=pat-insert]') && r.querySelector('[data-a=pat-skill]'))"), "")
    check("the Library tab is called Prompts", "Prompts" in ev(pg, "document.querySelector('.tabs').textContent"), ev(pg, "document.querySelector('.tabs').textContent"))
    seed = {"_about": "made-up seed of the owner's file shape", "patterns": [{"id": "pat-zz-01", "title": "Hunt test", "desc": "x", "body": "Hunt for {{topic}}.", "kind": "block", "createdAt": "2026-11-09T22:00:00.000Z", "cat": "surface", "fav": True},
                                                                            {"id": "pat-zz-02", "title": "Plain test", "desc": "y", "body": "Plain.", "kind": "block", "createdAt": "2026-11-09T22:00:00.000Z", "cat": "", "fav": False}]}
    imp = ev(pg, "(d) => { importBackup(d, 'seed.json'); const a = arr(WS.patterns).find(x => x.id === 'pat-zz-01'), b = arr(WS.patterns).find(x => x.id === 'pat-zz-02'); return {a: a && [a.cat, a.fav, a.src, a.opened], b: b && [b.cat, b.fav, b.src, prmOwnCat(b)], settings: WS.settings.lang}; }", seed)
    check("a seed-shaped file imports: category and ★ kept, marked as from outside, unopened; no category → Received", imp["a"] == ["surface", True, "import", False] and imp["b"] and imp["b"][3] == "received", imp)

    print("7 settings, phone, languages, Chinese typing")
    ev(pg, "() => { go('settings'); UI.setTab = 'general'; render(); }"); pg.wait_for_timeout(200)
    check("Settings › General has a Prompts section", ev(pg, "!!document.querySelector('[data-anchor=prm-settings]')"), "")
    pg.select_option("[data-anchor=prm-settings] select[data-k=prmOpen]", "fav"); pg.wait_for_timeout(150)
    pg.select_option("[data-anchor=prm-settings] select[data-k=prmOrder]", "az"); pg.wait_for_timeout(150)
    pg.locator("[data-anchor=prm-settings] input[data-k=prmStarters]").uncheck(); pg.wait_for_timeout(150)
    ev(pg, CHAT); pg.wait_for_timeout(200)
    pg.locator(".prm-btn[data-prm-for=c20-in]").first.click(); pg.wait_for_timeout(200)
    check("“opens on Favorites” is used", ev(pg, "PRM.cat") == "fav", ev(pg, "PRM.cat"))
    ev(pg, "() => { PRM.cat = 'all'; prmDraw(); }")
    titles = ev(pg, "[...document.querySelectorAll('#prm-layer .prm-row')].map(r => r.querySelector('.prm-head b').textContent)")
    favs = ev(pg, "prmAll().filter(x => x.fav).length")
    rest = titles[favs:]
    check("A–Z order (★ still on top) and no starters", rest == sorted(rest, key=lambda s: s.lower()) and not ev(pg, "prmAll().some(x => x.cat === 'starter')"), titles)
    ev(pg, "prmClose()")
    ev(pg, "() => { go('settings'); UI.setTab = 'general'; render(); }"); pg.wait_for_timeout(200)
    pg.locator("[data-anchor=prm-settings] input[data-k=prmBtn]").uncheck(); pg.wait_for_timeout(150)
    ev(pg, CHAT); pg.wait_for_timeout(200)
    check("the button can be switched off", not ev(pg, "!!document.querySelector('.prm-btn')"), "")
    check("these settings are flat keys a backup restores", ev(pg, "['prmBtn','prmOpen','prmOrder','prmStarters'].every(k => IMPORT_SETTINGS.includes(k))"), "")
    ev(pg, "() => { for (const k of ['prmBtn', 'prmOpen', 'prmOrder', 'prmStarters']) delete WS.settings[k]; render(); }")
    pg.locator(".prm-btn[data-prm-for=c20-in]").first.click(); pg.wait_for_timeout(200)
    ev(pg, "() => { PRM.cat = 'all'; prmDraw(); }")
    ident = ev(pg, "() => { window.__listEl = document.getElementById('prm-list').firstElementChild; const q = document.getElementById('prm-q'); q.focus(); q.dispatchEvent(new CompositionEvent('compositionstart', {bubbles: true}));"
               " for (const v of ['g', 'ga', 'gam']){ q.value = v; q.dispatchEvent(new InputEvent('input', {bubbles: true, isComposing: true})); } return document.getElementById('prm-list').firstElementChild === window.__listEl && document.activeElement === q; }")
    ev(pg, "() => { const q = document.getElementById('prm-q'); q.value = 'gamma'; q.dispatchEvent(new CompositionEvent('compositionend', {bubbles: true, data: 'gamma'})); }"); pg.wait_for_timeout(100)
    after = ev(pg, "[...document.querySelectorAll('#prm-layer .prm-row')].map(r => r.dataset.id)")
    check("Chinese typing in the search: no redraw while composing, the list filters when the characters are confirmed", ident and after == ["pt-tC"], [ident, after])
    ev(pg, "prmClose()")
    pg.set_viewport_size({"width": 390, "height": 844}); pg.wait_for_timeout(200)
    pg.locator(".prm-btn[data-prm-for=c20-in]").first.click(); pg.wait_for_timeout(250)
    ph = ev(pg, "(() => { const p = document.querySelector('.prm-pop').getBoundingClientRect(); const bs = [...document.querySelectorAll('#prm-layer .prm-acts .btn')].map(b => b.getBoundingClientRect().height); return {w: p.width, bottom: Math.round(innerHeight - p.bottom), min: Math.min(...bs), scroll: document.documentElement.scrollWidth <= innerWidth + 1}; })()")
    check("on a phone the list is a sheet from the bottom, its buttons at least 44 px, no sideways scroll", ph["w"] >= 389 and ph["bottom"] <= 1 and ph["min"] >= 44 and ph["scroll"], ph)
    ev(pg, "prmClose()")
    pg.set_viewport_size({"width": 1280, "height": 900})
    for lang, word in (("de", "Meine Prompts"), ("zh", "我的提示词")):
        ev(pg, f"() => {{ ACTIONS['set-lang']({{dataset: {{l: '{lang}'}}}}); }}"); ev(pg, CHAT); pg.wait_for_timeout(200)
        pg.locator(".prm-btn[data-prm-for=c20-in]").first.click(); pg.wait_for_timeout(200)
        check(f"the list in {lang}", word in ev(pg, "document.querySelector('#prm-layer').textContent"), lang)
        ev(pg, "prmClose()")
    ev(pg, "() => { ACTIONS['set-lang']({dataset: {l: 'en'}}); }")
    check("no page errors in the whole run", not errors, errors[:4])
    b.close()
print(f"\n== e2e220_prompts: ok: {len(oks)} failed: {len(fails)} page errors: {len(errors)}")
for f in fails: print("FAIL", f)
for e in errors[:10]: print("ERR ", e)
sys.exit(1 if fails or errors else 0)
